import React from 'react';
import { hydrate } from 'react-dom';
import { createApolloClient } from '@fede/utils';
/**
 * If App import is not before createPersistedQueryLink,
 * you will see 'utils.inherits is not a function'.
 * Why? ¯\_(ツ)_/¯
 */
import App from './components/App';
import { ApolloProvider } from '@apollo/client';
import fragmentTypes from '../fragmentTypes.json';
import { ProspectsProvider } from './ProspectsContext';
import { isBrowser } from './utils';

const rootSelector = document.querySelector('#root');
const initDataSelector = document.querySelector('[data-init-state]');
const initDataAttribute =
    initDataSelector && initDataSelector.getAttribute('data-init-state');

if (isBrowser() && rootSelector && initDataAttribute) {
    const initState = JSON.parse(initDataAttribute);
    const { appName, appVersion, context, payload } = initState || {};
    const { midfieldUrl } = context || {};

    const { client } = createApolloClient({
        appName,
        appVersion,
        cacheData: payload,
        configOptions: {
            possibleTypes: fragmentTypes.possibleTypes
        },
        isBrowser: true,
        url: midfieldUrl
    });

    const component = (
        <ApolloProvider client={client}>
            <ProspectsProvider initState={context}>
                <App />
            </ProspectsProvider>
        </ApolloProvider>
    );

    initDataSelector.removeAttribute('data-init-state');
    hydrate(component, rootSelector);

    window.mlbDoubleclick.init({
        adUnitHierarchy2: '/prospects'
    });
}
